def components(A, val=1):
    A=np.array(A); seen=np.zeros_like(A,bool); comps=[]
    H,W=A.shape; for i in range(H):
        for j in range(W):
            if A[i,j]==val and not seen[i,j]:
                stack=[(i,j)]; seen[i,j]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny,nx] and A[ny,nx]==val:
                                seen[ny,nx]=True; stack.append((ny,nx))
                comps.append(np.array(cells))
    return comps
