G=load()
# Re-verify demos 2,3 outputs with transpose/flip rule; check noise structure of test block carefully.
Bi=np.array(G['Demo pair 1 output']); B=getB(np.array(G['Demo pair 1 input']))
ops={'id':lambda x:x,'rotcw':np.rot90(-1),'rotccw':np.rot90(1),'rot180':np.rot90(2),
     'flipud':np.flipud,'fliplr':np.fliplr,'T':np.transpose}
for nm in ('1','2','3'):
    Ai=G[f'Demo pair {nm} input']; Bi_=np.array(G[f'Demo pair {nm} output'])
    B=getB(np.array(Ai))
    print('=== demo',nm,B.shape,Bi_.shape)
    sols=[]
    for n,op in ops.items():
        Y=op(B)
        if list(Y.shape)==list(Bi_.shape):
            sols.append((n,int(np.sum(Y!=Bi_))))
    print('  candidates:',sols)
    if sols: 
        n,s=sols[0]; Y=ops[n](B); d=np.argwhere(Y!=Bi_)
        print('  best',n,'ndiff',len(d))
        for i,j in d: print('    ',i,j,'Y=',int(Y[i,j]),'out=',int(Bi_[i,j]))

